from collections import deque,Counter
def solve(a):
    h=len(a); w=len(a[0])
    cnt=Counter(x for r in a for x in r); bg=cnt.most_common(1)[0][0]
    seeds={}; sizes={}
    for i in range(h):
        j=0
        while j<w:
            if a[i][j]!=bg:
                k=j
                while k<w and a[i][k]==a[i][j]: k+=1
                seeds.setdefault(a[i][j],[]).append((i,j)); sizes[a[i][j]]=sizes.get(a[i][j],0)+ (k-j)
                j=k
            else: j+=1
    pc=min(seeds,key=lambda v:sizes[v])  # painter = color with fewer total cells
    tc=[v for v in seeds if v!=pc][0]
    dist=[[None]*w for _ in range(h)]; par=[[None]*w for _ in range(h)]; q=deque()
    for s in seeds[pc]: dist[s[0]][s[1]]=0; q.append(s)
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and a[ni][nj]==bg and dist[ni][nj] is None:
                dist[ni][nj]=dist[i][j]+1; par[ni][nj]=(i,j); q.append((ni,nj))
    return bg,seeds,pc,tc,dist,par
