        return sum(1 for di in(-1,0,1) for dj in(-1,0,1) if (di or dj) and 0<=i+di<h and 0<=j+dj<w and g[i+di][j+dj] not in (bg,3,2))
    dist={}
    heap=[]
    for s in tb: dist[s]=(0,-hugs(*s)); heapq.heappush(heap,dist[s]); par={s:None for s in tb}
    while heap:
        d,_=heapq.heappop(heap)
        cur=d[_]
        if dist.get(_)>d: continue
